package main

import (
	"bytes"
	"fmt"
	"path/filepath"
	"regexp"
	"strconv"
)

// paint/tabs.md#info岛状变体; these are RGB inks, alpha is a metric.
var outlineColors = [][2]string{{"profileTabs.outlineLight", "#000000ff"}, {"profileTabs.outlineDark", "#ffffffff"}}

// The checked-in generated palette is a complete record including semantic
// aliases. Rebuild its accessors without opening either upstream checkout.
func generateRecordedColors(out string) {
	data := mustRead(filepath.Join(out, "theme/colors_gen.go"))
	rows := regexp.MustCompile(`\{("[^"]+"),\s*("[^"]+"),\s*("[^"]+")\},([^\n]*)`).FindAllSubmatch(data, -1)
	var keys []string
	var body bytes.Buffer
	seen := map[string]bool{}
	for _, r := range rows {
		key, err := strconv.Unquote(string(r[1]))
		must(err)
		keys = append(keys, key)
		seen[key] = true
		fmt.Fprintf(&body, "{%s,%s,%s},%s\n", r[1], r[2], r[3], r[4])
	}
	for _, r := range outlineColors {
		if seen[r[0]] {
			continue
		}
		keys = append(keys, r[0])
		fmt.Fprintf(&body, "{%q,%q,%q}, // paint/tabs.md#info岛状变体\n", r[0], r[1], r[1])
	}
	var b bytes.Buffer
	b.WriteString("// Code generated by internal/cmd/themegen; DO NOT EDIT.\npackage theme\nimport \"github.com/egoist/mygo/ui\"\n")
	accessors(&b, "Colors", "ui.Color", keys)
	b.WriteString("var colorSpecs = [...]colorSpec{\n")
	b.Write(body.Bytes())
	b.WriteString("}\n")
	saveGo(out, "theme/colors_gen.go", b.Bytes())
	fmt.Printf("Generated %d recorded colors.\n", len(keys))
}
